CREATE TABLE IF NOT EXISTS long_translation_exercises (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  title TEXT NOT NULL,
  source TEXT NOT NULL,
  translation TEXT NOT NULL,
  difficulty TEXT CHECK(difficulty IN ('easy', 'medium', 'hard')) DEFAULT 'medium',
  category TEXT DEFAULT 'administrative',
  word_count INTEGER DEFAULT 0
);

INSERT INTO long_translation_exercises (title, source, translation, difficulty, category, word_count) VALUES
-- Politique
('Allocution présidentielle', 'In these unprecedented times, our nation must demonstrate unity and resilience. The forthcoming legislative session will address fundamental reforms touching upon civil liberties, economic recovery, and our collective security. We owe it to future generations to leave them a country that is stronger, fairer, and more prosperous than the one we inherited.', 'Dans ces temps sans précédent, notre nation doit faire preuve d''unité et de résilience. La prochaine session législative examinera des réformes fondamentales touchant aux libertés civiles, à la reprise économique et à notre sécurité collective. Nous devons aux générations futures de leur laisser un pays plus fort, plus juste et plus prospère que celui que nous avons hérité.', 'medium', 'politique', 54),
('Réforme électorale', 'The proposed overhaul of the electoral system seeks to ensure greater transparency in campaign financing while strengthening the representation of minority communities. Proponents argue that these measures will restore public confidence in democratic institutions, whereas opponents fear an excessive centralisation of power within the executive branch.', 'La réforme proposée du système électoral vise à assurer une plus grande transparence dans le financement des campagnes tout en renforçant la représentation des communautés minoritaires. Les partisans soutiennent que ces mesures restaureront la confiance du public dans les institutions démocratiques, tandis que les opposants craignent une centralisation excessive du pouvoir au sein du pouvoir exécutif.', 'hard', 'politique', 52),
('Débat parlementaire', 'During yesterday''s heated parliamentary debate, opposition members challenged the government''s fiscal projections, citing independent analyses that suggest the deficit will exceed previously announced targets. The minister of finance defended the budgetary roadmap, emphasising that unforeseen global events had necessitated a recalibration of priorities.', 'Lors du débat parlementaire houleux d''hier, les membres de l''opposition ont contesté les projections budgétaires du gouvernement, citant des analyses indépendantes qui suggèrent que le déficit dépassera les objectifs précédemment annoncés. Le ministre des Finances a défendu la feuille de route budgétaire, soulignant que des événements mondiaux imprévus avaient nécessité un recalage des priorités.', 'hard', 'politique', 50),
('Crise institutionnelle', 'The mounting tensions between the legislative and judicial branches have raised concerns among constitutional experts. Several prominent jurists have called for renewed dialogue, warning that any attempt to circumvent judicial oversight could undermine the rule of law and set a dangerous precedent for future administrations.', 'Les tensions croissantes entre les pouvoirs législatif et judiciaire ont soulevé des inquiétudes parmi les experts constitutionnels. Plusieurs juristes éminents ont appelé à un dialogue renouvelé, avertissant que toute tentative de contourner la surveillance judiciaire pourrait saper l''état de droit et créer un dangereux précédent pour les futures administrations.', 'hard', 'politique', 48),
('Transparence publique', 'In response to growing public pressure, the government has committed to publishing ministerial expense reports on a quarterly basis. This measure, long demanded by civil society organisations, represents a significant step towards greater accountability within the executive branch.', 'En réponse aux pressions croissantes du public, le gouvernement s''est engagé à publier les rapports de dépenses ministérielles sur une base trimestrielle. Cette mesure, longtemps réclamée par les organisations de la société civile, représente un pas significatif vers une plus grande responsabilité au sein du pouvoir exécutif.', 'easy', 'politique', 43),
-- Économie
('Politique monétaire', 'The central bank''s monetary policy committee has signalled its intention to maintain the current interest rate, citing persistent inflationary pressures that continue to exceed the two-percent target. Financial markets reacted cautiously, with the yield curve flattening amid renewed uncertainty about the timing of future rate adjustments.', 'Le comité de politique monétaire de la banque centrale a signalé son intention de maintenir le taux d''intérêt actuel, invoquant des pressions inflationnistes persistantes qui continuent de dépasser l''objectif de deux pour cent. Les marchés financiers ont réagi avec prudence, la courbe des rendements s''aplatissant dans un contexte d''incertitude renouvelée quant au calendrier des futurs ajustements de taux.', 'hard', 'economie', 52),
('Marché du travail', 'Labour market indicators released this morning reveal a modest uptick in unemployment among young graduates, raising concerns about the effectiveness of current vocational training programmes. Economists attribute this trend to structural mismatches between educational curricula and the evolving demands of the digital economy.', 'Les indicateurs du marché du travail publiés ce matin révèlent une légère hausse du chômage parmi les jeunes diplômés, suscitant des inquiétudes quant à l''efficacité des programmes actuels de formation professionnelle. Les économistes attribuent cette tendance aux désajustements structurels entre les programmes d''enseignement et les exigences évolutives de l''économie numérique.', 'medium', 'economie', 50),
('Fiscalité', 'The proposed overhaul of the corporate tax code seeks to eliminate loopholes that have allowed multinational enterprises to shift profits to low-tax jurisdictions. Revenue authorities estimate that closing these gaps could generate an additional fifteen billion euros in annual tax receipts.', 'La réforme proposée du code fiscal des sociétés vise à éliminer les failles qui ont permis aux entreprises multinationales de transférer leurs profits vers des juridictions à faible fiscalité. Les autorités fiscales estiment que la fermeture de ces lacunes pourrait générer quinze milliards d''euros supplémentaires en recettes fiscales annuelles.', 'medium', 'economie', 48),
('Dette publique', 'The national debt-to-GDP ratio has climbed to levels not seen since the post-war reconstruction period. While the minister of finance insists that current borrowing supports essential infrastructure, opposition parties have called for a credible medium-term consolidation plan.', 'Le ratio dette publique / PIB est monté à des niveaux inédits depuis la période de reconstruction d''après-guerre. Alors que le ministre des Finances insiste sur le fait que les emprunts actuels financent des infrastructures essentielles, les partis d''opposition ont réclamé un plan crédible de consolidation à moyen terme.', 'medium', 'economie', 47),
('Économie verte', 'The transition to a low-carbon economy is expected to create two million new jobs over the next decade, albeit with significant retraining requirements for workers in sunset industries. Public-private partnerships will be essential to financing the necessary grid modernisation.', 'La transition vers une économie à faible émission de carbone devrait créer deux millions de nouveaux emplois au cours de la prochaine décennie, bien qu''avec des besoins significatifs de reconversion pour les travailleurs des industries en déclin. Les partenariats public-privé seront essentiels pour financer la modernisation nécessaire des réseaux.', 'medium', 'economie', 48),
('Crise énergétique', 'Soaring wholesale energy prices have placed unprecedented strain on household budgets and industrial competitiveness. The government has announced temporary price caps and targeted subsidies for vulnerable households, while accelerating permits for renewable energy projects.', 'La flambée des prix de l''énergie de gros a mis une pression sans précédent sur les budgets des ménages et la compétitivité industrielle. Le gouvernement a annoncé des plafonnements temporaires des prix et des subventions ciblées pour les ménages vulnérables, tout en accélérant les permis pour les projets d''énergies renouvelables.', 'medium', 'economie', 48),
-- Société
('Éducation nationale', 'The ministry of education has unveiled an ambitious curriculum reform aimed at reducing educational inequalities between urban and rural areas. Key provisions include smaller class sizes in disadvantaged neighbourhoods and the deployment of broadband connectivity to every secondary school by the end of the academic year.', 'Le ministère de l''Éducation a dévoilé une ambitieuse réforme des programmes visant à réduire les inégalités éducatives entre les zones urbaines et rurales. Les dispositions clés incluent des effectifs réduits dans les quartiers défavorisés et le déploiement de la connectivité à haut débit dans chaque école secondaire d''ici la fin de l''année scolaire.', 'easy', 'societe', 51),
('Santé publique', 'Public health authorities have issued an urgent appeal for blood donations following a critical shortage in hospital reserves. The campaign specifically targets younger donors, whose participation rates have declined steadily over the past five years due to lingering misconceptions about the donation process.', 'Les autorités sanitaires ont lancé un appel urgent pour les dons de sang suite à une pénurie critique dans les réserves hospitalières. La campagne cible spécifiquement les jeunes donateurs, dont les taux de participation ont régulièrement baissé au cours des cinq dernières années en raison de idées reçues persistantes sur le processus de don.', 'easy', 'societe', 50),
('Inégalités', 'Recent census data confirms a widening gap in life expectancy between the wealthiest and poorest neighbourhoods. Public health researchers have called for targeted interventions in early childhood, arguing that nutritional and educational disadvantages compound over time to produce starkly divergent outcomes.', 'Les récentes données du recensement confirment un écart croissant dans l''espérance de vie entre les quartiers les plus riches et les plus pauvres. Les chercheurs en santé publique ont appelé à des interventions ciblées dans la petite enfance, soutenant que les désavantages nutritionnels et éducatifs se cumulent au fil du temps pour produire des résultats nettement divergents.', 'hard', 'societe', 50),
('Vieillissement', 'With the retirement age population projected to double within two decades, policymakers are scrambling to redesign pension systems and expand geriatric care capacity. Intergenerational solidarity has emerged as a central theme in public discourse, with younger workers expressing anxiety about future contribution rates.', 'Avec la population des retraités qui devrait doubler en deux décennies, les décideurs politiques se précipitent pour refondre les systèmes de retraite et augmenter la capacité de soins gériatriques. La solidarité intergénérationnelle est apparue comme un thème central dans le discours public, les travailleurs plus jeunes exprimant leur inquiétude quant aux futurs taux de cotisation.', 'medium', 'societe', 51),
('Cohésion sociale', 'Community leaders in disadvantaged suburbs have called for greater investment in youth centres and sports facilities as a means of preventing juvenile delinquency. They argue that punitive approaches alone have failed to address the root causes of antisocial behaviour, which often stem from economic marginalisation and educational disengagement.', 'Les responsables communautaires dans les banlieues défavorisées ont appelé à un investissement plus important dans les centres de jeunesse et les installations sportives comme moyen de prévenir la délinquance juvénile. Ils soutiennent que les approches répressives seules ont échoué à traiter les causes profondes des comportements antisociaux, qui découlent souvent de la marginalisation économique et du désengagement scolaire.', 'hard', 'societe', 55),
-- Jeux vidéo
('Industrie du jeu vidéo', 'The domestic video game industry has grown to become the third-largest entertainment sector, generating annual revenues exceeding those of cinema and recorded music combined. Independent studios, in particular, have flourished thanks to accessible publishing platforms and a vibrant community of early-access testers.', 'L''industrie nationale du jeu vidéo est devenue le troisième plus grand secteur du divertissement, générant des revenus annuels supérieurs à ceux du cinéma et de la musique enregistrée combinés. Les studios indépendants, en particulier, se sont épanouis grâce à des plateformes de publication accessibles et à une communauté dynamique de testeurs en accès anticipé.', 'medium', 'jeux_video', 49),
('Régulation des lootboxes', 'Following several high-profile lawsuits, the consumer protection authority has classified randomized in-game purchases as a form of gambling, requiring developers to disclose drop rates and implement parental controls. Industry representatives warn that overly restrictive frameworks could stifle innovation and reduce investment in domestic development.', 'Suite à plusieurs procès retentissants, l''autorité de protection des consommateurs a classé les achats aléatoires en jeu comme une forme de jeu d''argent, exigeant des développeurs qu''ils divulguent les taux de drop et mettent en place des contrôles parentaux. Les représentants de l''industrie mettent en garde que des cadres trop restrictifs pourraient étouffer l''innovation et réduire l''investissement dans le développement national.', 'hard', 'jeux_video', 52),
('Esport', 'Professional esports leagues have attracted multimillion-dollar sponsorship deals from mainstream brands seeking to reach younger demographics. Olympic committees are now actively debating the inclusion of competitive gaming in future programmes, citing the strategic thinking and teamwork required at the highest levels of play.', 'Les ligues professionnelles d''esport ont attiré des contrats de sponsoring multimillionnaires de marques grand public cherchant à atteindre des démographies plus jeunes. Les comités olympiques débattent désormais activement de l''inclusion du jeu compétitif dans les futurs programmes, invoquant la réflexion stratégique et le travail d''équipe requis aux plus hauts niveaux de jeu.', 'medium', 'jeux_video', 51),
('Accessibilité', 'Advocacy groups for players with disabilities have secured commitments from major publishers to implement customisable control schemes, colour-blind modes, and subtitle options as standard features. These measures, once considered niche, are increasingly recognised as essential to ensuring equitable access to interactive entertainment.', 'Les groupes de défense des joueurs handicapés ont obtenu des engagements des grands éditeurs pour mettre en œuvre des schémas de contrôle personnalisables, des modes daltoniens et des options de sous-titres comme fonctionnalités standard. Ces mesures, autrefois considérées comme de niche, sont de plus en plus reconnues comme essentielles pour assurer un accès équitable au divertissement interactif.', 'medium', 'jeux_video', 53),
('Réalité virtuelle', 'Virtual reality headsets have reached price points that make mass-market adoption increasingly plausible. Educational institutions are already experimenting with immersive simulations for history and science curricula, though concerns persist about the long-term effects of extended exposure on visual development in younger users.', 'Les casques de réalité virtuelle ont atteint des prix rendant l''adoption grand public de plus en plus plausible. Les institutions éducatives expérimentent déjà des simulations immersives pour les programmes d''histoire et de sciences, bien que des inquiétudes persistent quant aux effets à long terme d''une exposition prolongée sur le développement visuel des jeunes utilisateurs.', 'medium', 'jeux_video', 51),
-- Technologie
('Intelligence artificielle', 'The rapid deployment of generative artificial intelligence across public administration has prompted an urgent review of data protection protocols. Civil servants have expressed concern that automated decision-making systems may inadvertently perpetuate existing biases embedded in historical training datasets.', 'Le déploiement rapide de l''intelligence artificielle générative dans l''administration publique a suscité un examen urgent des protocoles de protection des données. Les fonctionnaires ont exprimé leur inquiétude que les systèmes de prise de décision automatisée puissent involontairement perpétuer les biais existants incrustés dans les ensembles de données d''entraînement historiques.', 'hard', 'technologie', 50),
('Cybersécurité', 'The national cybersecurity agency has issued an advisory warning of heightened threat levels targeting critical infrastructure operators. Recommended countermeasures include multi-factor authentication for all remote access, network segmentation, and regular penetration testing by accredited third-party auditors.', 'L''agence nationale de cybersécurité a émis un avis mettant en garde contre des niveaux de menace accrus ciblant les opérateurs d''infrastructures critiques. Les contre-mesures recommandées incluent l''authentification multi-facteurs pour tous les accès à distance, la segmentation des réseaux et des tests de pénétration réguliers par des auditeurs tiers accrédités.', 'hard', 'technologie', 49),
('Protection des données', 'The data protection authority has imposed its largest fine to date on a major technology firm for unlawful processing of biometric information. The ruling establishes a significant precedent, clarifying that consent must be explicitly obtained and freely given before any facial recognition data may be collected.', 'L''autorité de protection des données a infligé sa plus lourde amende à ce jour à une grande entreprise technologique pour le traitement illégal d''informations biométriques. La décision établit un précédent significatif, précisant que le consentement doit être explicitement obtenu et librement donné avant que toute donnée de reconnaissance faciale puisse être collectée.', 'hard', 'technologie', 50),
('5G et infrastructure', 'The nationwide rollout of fifth-generation mobile networks has reached eighty percent coverage in urban areas, with rural deployment scheduled to accelerate next year. Telecom operators have pledged to maintain open access principles, ensuring that smaller internet service providers can compete on equal terms.', 'Le déploiement national des réseaux mobiles de cinquième génération a atteint une couverture de quatre-vingt pour cent dans les zones urbaines, le déploiement rural étant prévu pour s''accélérer l''année prochaine. Les opérateurs de télécommunications se sont engagés à maintenir les principes d''accès ouvert, veillant à ce que les plus petits fournisseurs d''accès à Internet puissent concourir à égalité.', 'medium', 'technologie', 52),
('Transformation numérique', 'The accelerated digital transformation of public services has yielded measurable improvements in processing times for routine administrative requests. However, digital literacy gaps among older citizens have widened, prompting the deployment of in-person assistance desks in municipal offices nationwide.', 'La transformation numérique accélérée des services publics a produit des améliorations mesurables des délais de traitement pour les demandes administratives courantes. Cependant, les écarts d''alphabétisation numérique parmi les personnes âgées se sont creusés, incitant au déploiement de guichets d''assistance en personne dans les bureaux municipaux à l''échelle nationale.', 'medium', 'technologie', 51),
-- Environnement
('Changement climatique', 'The latest intergovernmental report on climate change paints a sobering picture of accelerating glacier melt and rising sea levels. Coastal municipalities are now legally required to integrate adaptive measures into urban planning, including elevated infrastructure and managed retreat programmes for the most vulnerable zones.', 'Le dernier rapport intergouvernemental sur le changement climatique brosse un tableau inquiétant de l''accélération de la fonte des glaciers et de la montée des eaux. Les municipalités côtières sont désormais légalement tenues d''intégrer des mesures d''adaptation dans la planification urbaine, y compris des infrastructures surélevées et des programmes de retrait géré pour les zones les plus vulnérables.', 'hard', 'environnement', 52),
('Biodiversité', 'Conservation biologists have identified seventeen previously unknown species in the newly designated marine reserve. The discovery underscores the importance of expanding protected areas, particularly in regions where industrial fishing and offshore drilling have degraded underwater ecosystems over several decades.', 'Les biologistes de la conservation ont identifié dix-sept espèces jusqu''alors inconnues dans la réserve marine nouvellement désignée. La découverte souligne l''importance d''étendre les zones protégées, particulièrement dans les régions où la pêche industrielle et le forage offshore ont dégradé les écosystèmes sous-marins sur plusieurs décennies.', 'medium', 'environnement', 49),
('Énergie renouvelable', 'The national energy transition plan sets a binding target of sixty-five percent renewable electricity by twenty thirty-five. Major investments in offshore wind and green hydrogen are complemented by regulatory reforms designed to streamline permitting and encourage community ownership of generation assets.', 'Le plan national de transition énergétique fixe un objectif contraignant de soixante-cinq pour cent d''électricité renouvelable d''ici vingt trente-cinq. D''importants investissements dans l''éolien offshore et l''hydrogène vert sont complétés par des réformes réglementaires conçues pour simplifier les permis et encourager la propriété communautaire des actifs de production.', 'medium', 'environnement', 50),
('Agriculture durable', 'Agricultural extension services are promoting regenerative farming practices that restore soil health while maintaining commercially viable yields. Pilot programmes have demonstrated that reduced tillage and diversified crop rotation can sequester significant quantities of atmospheric carbon over a ten-year horizon.', 'Les services de vulgarisation agricole promeuvent des pratiques d''agriculture régénérative qui restaurent la santé des sols tout en maintenant des rendements commercialement viables. Les programmes pilotes ont démontré que le labour réduit et la rotation diversifiée des cultures peuvent séquestrer des quantités significatives de carbone atmosphérique sur un horizon de dix ans.', 'medium', 'environnement', 49),
-- Sport
('Sport et inclusion', 'The national sports federation has adopted a comprehensive inclusion policy mandating accessibility audits for all major sporting venues. Wheelchair seating, sensory rooms for neurodivergent spectators, and sign-language interpretation services must now be provided at every professional league match.', 'La fédération sportive nationale a adopté une politique d''inclusion complète imposant des audits d''accessibilité pour tous les grands sites sportifs. Les places pour fauteuils roulants, les salles sensorielles pour les spectateurs neurodivergents et les services d''interprétation en langue des signes doivent désormais être fournis à chaque match de ligue professionnelle.', 'medium', 'sport', 47),
('JOP 2024', 'The organisation of major international sporting events requires seamless coordination between public authorities, private contractors, and international federations. Security planning alone encompasses tens of thousands of personnel, multi-layered threat assessments, and contingency protocols for every conceivable scenario.', 'L''organisation de grands événements sportifs internationaux nécessite une coordination transparente entre les autorités publiques, les entrepreneurs privés et les fédérations internationales. La planification de la sécurité à elle seule englobe des dizaines de milliers de personnels, des évaluations des menaces multicouches et des protocoles de contingence pour chaque scénario concevable.', 'hard', 'sport', 48),
('Sport amateur', 'Municipal investment in grassroots sports facilities has yielded measurable improvements in adolescent physical activity levels. A recent longitudinal study found that teenagers with access to free neighbourhood courts and pitches were forty percent more likely to meet recommended exercise guidelines.', 'L''investissement municipal dans les installations sportives de base a produit des améliorations mesurables des niveaux d''activité physique des adolescents. Une récente étude longitudinale a trouvé que les adolescents ayant accès à des terrains de quartier gratuits étaient quarante pour cent plus susceptibles de respecter les recommandations d''exercice.', 'easy', 'sport', 47),
('Économie du sport', 'The professional football league has signed a record broadcasting rights deal valued at over four billion euros over five seasons. Critics argue that this financial concentration exacerbates competitive inequality, as smaller clubs cannot match the wage bills and infrastructure investments of dominant metropolitan teams.', 'La ligue professionnelle de football a signé un contrat record de droits de diffusion évalué à plus de quatre milliards d''euros sur cinq saisons. Les critiques soutiennent que cette concentration financière exacerbe l''inégalité compétitive, les petits clubs ne pouvant égaler les masses salariales et les investissements en infrastructure des grandes équipes métropolitaines.', 'medium', 'sport', 49),
-- Justice
('Réforme judiciaire', 'The minister of justice has presented a sweeping reform of criminal procedure designed to reduce pre-trial detention and expedite the handling of minor offences. Defence bar associations have cautiously welcomed the proposals while demanding guarantees that judicial independence will not be compromised.', 'Le ministre de la Justice a présenté une réforme globale de la procédure pénale conçue pour réduire la détention préventive et accélérer le traitement des infractions mineures. Les barreaux de la défense ont accueilli avec prudence les propositions tout en réclamant des garanties que l''indépendance judiciaire ne sera pas compromise.', 'hard', 'justice', 49),
('État de droit', 'The constitutional court has annulled several provisions of the new security legislation, finding that they violated fundamental procedural safeguards. The ruling reasserts the judiciary''s authority to review legislative compliance with constitutional principles, even in matters pertaining to national security.', 'La cour constitutionnelle a annulé plusieurs dispositions de la nouvelle législation sur la sécurité, estimant qu''elles violaient les garanties procédurales fondamentales. La décision réaffirme l''autorité du judiciaire à examiner la conformité législative avec les principes constitutionnels, même dans les matières relatives à la sécurité nationale.', 'hard', 'justice', 46),
('Justice restaurative', 'Pilot programmes in restorative justice have demonstrated promising results in reducing recidivism among young offenders. By bringing victims and perpetrators into structured dialogue, these initiatives seek to repair harm and reintegrate participants into their communities, rather than relying solely on custodial sentences.', 'Les programmes pilotes en justice restaurative ont démontré des résultats prometteurs dans la réduction de la récidive chez les jeunes délinquants. En réunissant victimes et auteurs dans un dialogue structuré, ces initiatives cherchent à réparer le préjudice et à réintégrer les participants dans leurs communautés, plutôt que de s''appuyer uniquement sur des peines d''emprisonnement.', 'medium', 'justice', 50),
-- Immigration
('Politique migratoire', 'The government has unveiled a new immigration framework that prioritises skilled labour migration while tightening family reunification criteria. Human rights organisations have expressed concern that the revised points system may discriminate against applicants from non-English-speaking countries.', 'Le gouvernement a dévoilé un nouveau cadre migratoire qui donne la priorité à la migration de main-d''œuvre qualifiée tout en resserrant les critères de regroupement familial. Les organisations de défense des droits humains ont exprimé leur inquiétude que le système de points révisé puisse discriminer les candidats de pays non anglophones.', 'medium', 'immigration', 47),
('Intégration', 'Civic integration programmes have been expanded to include language instruction, labour market orientation, and constitutional literacy. Evaluation data indicates that participants who complete the full twelve-month curriculum achieve significantly higher employment rates than those who exit prematurely.', 'Les programmes d''intégration civique ont été élargis pour inclure l''enseignement de la langue, l''orientation vers le marché du travail et la connaissance de la constitution. Les données d''évaluation indiquent que les participants qui achèvent le programme complet de douze mois atteignent des taux d''emploi significativement plus élevés que ceux qui abandonnent prématurément.', 'medium', 'immigration', 48),
('Asile', 'The asylum processing backlog has reached a record high, with applicants waiting an average of eighteen months for an initial decision. The ministry has pledged to recruit two hundred additional case officers and digitise documentary evidence submission to reduce waiting times to under six months.', 'L''arriéré des demandes d''asile a atteint un niveau record, les demandeurs attendant en moyenne dix-huit mois pour une décision initiale. Le ministère s''est engagé à recruter deux cents agents de traitement supplémentaires et à numériser la soumission des pièces justificatives pour réduire les délais à moins de six mois.', 'medium', 'immigration', 48),
-- Urbanisme
('Logement abordable', 'The acute shortage of affordable rental housing has prompted the adoption of inclusionary zoning regulations requiring developers to set aside twenty percent of new units for social housing. Property industry representatives argue that these mandates increase construction costs and deter private investment.', 'La pénurie aiguë de logements locatifs abordables a incité à l''adoption de réglementations de zonage inclusif exigeant des promoteurs qu''ils réservent vingt pour cent des nouvelles unités au logement social. Les représentants de l''industrie immobilière soutiennent que ces mandats augmentent les coûts de construction et dissuadent l''investissement privé.', 'medium', 'urbanisme', 48),
('Mobilité urbaine', 'The metropolitan transport authority has approved a fifteen-year expansion plan for light rail and bus rapid transit corridors. The scheme aims to reduce private vehicle dependency by forty percent, though critics question whether the projected ridership figures adequately account for the rise of remote working patterns.', 'L''autorité de transport métropolitaine a approuvé un plan d''expansion de quinze ans pour les couloirs de tramway et de bus à haut niveau de service. Le projet vise à réduire la dépendance aux véhicules privés de quarante pour cent, bien que les critiques s''interrogent sur la prise en compte adéquate des chiffres de fréquentation projetés face à la montée du télétravail.', 'medium', 'urbanisme', 49),
('Aménagement durable', 'Urban planners are increasingly incorporating green corridors and pocket parks into dense residential developments. These biophilic design elements not only mitigate the urban heat island effect but also provide critical habitat connectivity for pollinator species displaced by construction activity.', 'Les urbanistes intègrent de plus en plus des corridors verts et des micro-parcs dans les aménagements résidentiels denses. Ces éléments de design biophile atténuent non seulement l''effet d''îlot de chaleur urbain mais fournissent également une connectivité d''habitat critique pour les espèces pollinisatrices déplacées par l''activité de construction.', 'hard', 'urbanisme', 48),
-- Sécurité
('Sûreté nationale', 'The ministry of the interior has outlined a comprehensive strategy to combat radicalisation in online spaces, combining automated content detection with community outreach programmes. Civil liberties groups have cautioned that algorithmic monitoring must be subject to judicial authorisation and transparent oversight mechanisms.', 'Le ministère de l''Intérieur a esquissé une stratégie globale pour lutter contre la radicalisation dans les espaces en ligne, combinant la détection automatisée de contenu avec des programmes de proximité communautaire. Les groupes de libertés civiles ont mis en garde que la surveillance algorithmique doit être soumise à une autorisation judiciaire et à des mécanismes de supervision transparents.', 'hard', 'securite', 50),
('Désinformation', 'State-backed disinformation campaigns have increasingly targeted electoral processes in democratic nations. Countermeasures include media literacy education, rapid fact-checking protocols, and international cooperation frameworks designed to expose and attribute coordinated inauthentic behaviour.', 'Les campagnes de désinformation soutenues par des États ciblent de plus en plus les processus électoraux dans les nations démocratiques. Les contre-mesures incluent l''éducation aux médias, des protocoles de vérification rapide des faits et des cadres de coopération internationale conçus pour exposer et attribuer les comportements coordonnés non authentiques.', 'hard', 'securite', 45),
('Police de proximité', 'The national police force has launched a community policing pilot in thirty neighbourhoods, assigning dedicated officers to foot patrols and local schools. Early evaluation data suggests a twelve-percent reduction in property crime, though residents remain divided on whether visibility alone guarantees lasting behavioural change.', 'La police nationale a lancé un pilote de police de proximité dans trente quartiers, affectant des officiers dédiés aux patrouilles à pied et aux écoles locales. Les premières données d''évaluation suggèrent une réduction de douze pour cent de la criminalité contre les biens, bien que les résidents restent partagés sur la question de savoir si la seule visibilité garantit un changement comportemental durable.', 'medium', 'securite', 51),
('Cybercriminalité', 'The organised crime unit has dismantled an international network responsible for ransomware attacks against hospitals and municipalities. The operation, conducted in cooperation with agencies in four countries, resulted in the seizure of cryptocurrency assets valued at approximately twenty million euros.', 'L''unité de lutte contre le crime organisé a démantelé un réseau international responsable d''attaques par rançongiciel contre des hôpitaux et des municipalités. L''opération, menée en coopération avec des agences de quatre pays, a abouti à la saisie d''actifs en cryptomonnaie d''une valeur d''environ vingt millions d''euros.', 'medium', 'securite', 48),
-- International
('Coopération humanitaire', 'The humanitarian response to the regional crisis has mobilised emergency supplies, medical personnel, and engineering teams from twelve donor nations. Coordination challenges remain acute, however, as competing mandates and bureaucratic entry requirements continue to delay the delivery of life-saving assistance to displaced populations.', 'La réponse humanitaire à la crise régionale a mobilisé des fournitures d''urgence, du personnel médical et des équipes d''ingénieurs de douze nations donatrices. Les défis de coordination restent cependant aigus, les mandats concurrents et les exigences bureaucratiques d''entrée continuant de retarder la livraison d''assistance vitale aux populations déplacées.', 'hard', 'international', 52),
('Diplomatie climatique', 'Climate diplomacy has emerged as a central pillar of foreign policy, with negotiators seeking binding commitments on methane reduction and deforestation. Developing nations have reiterated their demand for predictable climate finance, arguing that historical emitters bear a moral responsibility to fund adaptation efforts.', 'La diplomatie climatique est apparue comme un pilier central de la politique étrangère, les négociateurs recherchant des engagements contraignants sur la réduction du méthane et la déforestation. Les pays en développement ont réitéré leur demande de financement climatique prévisible, soutenant que les émetteurs historiques portent une responsabilité morale de financer les efforts d''adaptation.', 'hard', 'international', 50),
('Droits humains', 'The universal periodic review has recommended that the state ratify the optional protocol on economic, social, and cultural rights. Domestic human rights institutions have welcomed the recommendation while noting that implementation will require substantial legislative amendments and budgetary allocations.', 'L''examen périodique universel a recommandé que l''État ratifie le protocole facultatif relatif aux droits économiques, sociaux et culturels. Les institutions nationales des droits humains ont salué la recommandation tout en notant que sa mise en œuvre nécessitera des amendements législatifs substantiels et des allocations budgétaires.', 'hard', 'international', 48),
('Commerce équitable', 'The fair trade certification programme has expanded to cover artisanal mining cooperatives in three additional countries. Participating cooperatives must demonstrate compliance with labour standards, environmental remediation plans, and transparent revenue distribution to local communities.', 'Le programme de certification du commerce équitable s''est étendu pour couvrir les coopératives minières artisanales dans trois pays supplémentaires. Les coopératives participantes doivent démontrer leur conformité aux normes du travail, aux plans de remédiation environnementale et à une distribution transparente des revenus aux communautés locales.', 'medium', 'international', 47),
-- Santé
('Système de santé', 'The ministry of health has announced a major reorganisation of primary care networks, shifting resources from hospital-centric models to community-based preventive services. General practitioners will assume expanded coordination roles, managing multidisciplinary teams that include nurses, physiotherapists, and mental health counsellors.', 'Le ministère de la Santé a annoncé une réorganisation majeure des réseaux de soins primaires, transférant les ressources des modèles centrés sur l''hôpital vers des services préventifs communautaires. Les médecins généralistes assumeront des rôles de coordination élargis, gérant des équipes pluridisciplinaires incluant des infirmiers, des kinésithérapeutes et des conseillers en santé mentale.', 'medium', 'sante', 50),
('Télémédecine', 'The regulatory framework for telemedicine has been updated to permit asynchronous consultations and remote prescription of non-controlled medications. Medical associations have expressed cautious support, provided that diagnostic accuracy standards are maintained and that patient data is encrypted throughout the transmission chain.', 'Le cadre réglementaire de la télémédecine a été mis à jour pour permettre les consultations asynchrones et la prescription à distance de médicaments non soumis à contrôle. Les associations médicales ont exprimé un soutien prudent, à condition que les normes d''exactitude diagnostique soient maintenues et que les données des patients soient chiffrées tout au long de la chaîne de transmission.', 'hard', 'sante', 50),
('Santé mentale', 'Mental health services have received a forty-percent budget increase, enabling the hiring of four hundred additional psychiatrists and the creation of twenty-four-hour crisis response teams. Advocacy groups stress that reducing stigma remains equally important, calling for public awareness campaigns in schools and workplaces.', 'Les services de santé mentale ont bénéficié d''une augmentation budgétaire de quarante pour cent, permettant le recrutement de quatre cents psychiatres supplémentaires et la création d''équipes d''intervention de crise vingt-quatre heures sur vingt-quatre. Les groupes de défense soulignent que la réduction de la stigmatisation reste tout aussi importante, appelant à des campagnes de sensibilisation dans les écoles et les lieux de travail.', 'medium', 'sante', 50),
('Vaccination', 'The national immunisation programme has achieved a coverage rate of ninety-four percent for routine childhood vaccines. Public health officials attribute this success to school-based delivery programmes and reminder systems, though pockets of vaccine hesitancy persist in certain geographically isolated communities.', 'Le programme national de vaccination a atteint un taux de couverture de quatre-vingt-quatorze pour cent pour les vaccins infantiles de routine. Les responsables de la santé publique attribuent ce succès aux programmes de vaccination en milieu scolaire et aux systèmes de rappel, bien que des poches d''hésitation vaccinale persistent dans certaines communautés géographiquement isolées.', 'medium', 'sante', 50);

